// Silo level gauge: running average of the level probe on A2.
// Full-level lamp on D6, level report over UART.

const int PROBE_PIN = A2;
const int LAMP_PIN = 6;
const int WINDOW = 40;
const long FULL_MM = 4200;
const unsigned long SAMPLE_MS = 25;
const unsigned long REPORT_MS = 1000;

int readings[WINDOW];
int slot = 0;
long total = 0;
unsigned long lastSample = 0;
unsigned long lastReport = 0;

void takeSample()
{
    int raw = analogRead(PROBE_PIN);
    total -= readings[slot];
    readings[slot] = raw;
    total += raw;
    slot = (slot + 1) % WINDOW;
}

long averageMm()
{
    return (total * 5000L) / (1024L * WINDOW);
}

void showLamp()
{
    digitalWrite(LAMP_PIN, averageMm() >= FULL_MM ? HIGH : LOW);
}

void report()
{
    Serial.print("level ");
    Serial.print(averageMm());
    Serial.println(" mm");
}

void setup()
{
    pinMode(LAMP_PIN, OUTPUT);
    digitalWrite(LAMP_PIN, LOW);
    Serial.begin(9600);
    for (int i = 0; i < WINDOW; i++)
    {
        readings[i] = 0;
    }
    for (int i = 0; i < WINDOW; i++)
    {
        takeSample();
    }
    lastSample = millis();
    lastReport = millis();
    showLamp();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        takeSample();
        showLamp();
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
    }
}

// Tank mixer scheduler: 2 s of mixing in every 5 s cycle.
// Relay on D6, hold switch on D3 (pull-up).

const int MIXER_PIN = 6;
const int HOLD_PIN = 3;
const uint16_t RUN_MS = 2000;
const uint16_t CYCLE_MS = 5000;
const uint16_t HOLD_CONFIRM_MS = 50;

uint16_t nextRunAt = 0;
uint16_t stopRunAt = 0;
bool running = false;
unsigned int runCount = 0;

bool heldState = false;
bool heldCandidate = false;
uint16_t heldCandidateSince = 0;

uint16_t tickNow()
{
    return (uint16_t)millis();
}

void announceRun()
{
    Serial.print("mix ");
    Serial.println(runCount);
}

void startRun(uint16_t now)
{
    running = true;
    runCount++;
    stopRunAt = now + RUN_MS;
    nextRunAt = now + CYCLE_MS;
    announceRun();
}

void stopRun()
{
    running = false;
}

bool held()
{
    return heldState;
}

void updateHeld(uint16_t now)
{
    bool raw = digitalRead(HOLD_PIN) == LOW;
    if (raw != heldCandidate)
    {
        heldCandidate = raw;
        heldCandidateSince = now;
    }
    else if (heldCandidate != heldState)
    {
        if ((uint16_t)(now - heldCandidateSince) >= HOLD_CONFIRM_MS)
        {
            heldState = heldCandidate;
        }
    }
}

void drive()
{
    bool on = running && !held();
    digitalWrite(MIXER_PIN, on ? HIGH : LOW);
}

void setup()
{
    pinMode(MIXER_PIN, OUTPUT);
    pinMode(HOLD_PIN, INPUT_PULLUP);
    digitalWrite(MIXER_PIN, LOW);
    Serial.begin(9600);
    nextRunAt = tickNow() + CYCLE_MS;
}

void loop()
{
    uint16_t now = tickNow();
    updateHeld(now);
    if (running)
    {
        if (now >= stopRunAt)
        {
            stopRun();
        }
    }
    else if (now >= nextRunAt)
    {
        startRun(now);
    }
    drive();
}

// Meadow sprinkler zone: one 500 ms burst per start press.
// Valve relay on D10, start button on D6 (pull-up), status over UART.

const int ZONE_PIN = 10;
const int START_PIN = 6;
const unsigned long BURST_MS = 500;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool zoneOpen = false;
bool held = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long closeAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openZone()
{
    zoneOpen = true;
    closeAt = millis() + BURST_MS;
    digitalWrite(ZONE_PIN, HIGH);
    bursts++;
}

void closeZone()
{
    zoneOpen = false;
    digitalWrite(ZONE_PIN, LOW);
}

bool closeDue()
{
    return (long)(millis() - closeAt) >= 0;
}

void scanStart()
{
    int level = digitalRead(START_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !zoneOpen)
        {
            openZone();
        }
        held = down;
    }
}

void report()
{
    Serial.print("zone n=");
    Serial.println(bursts);
}

void setup()
{
    pinMode(ZONE_PIN, OUTPUT);
    pinMode(START_PIN, INPUT_PULLUP);
    digitalWrite(ZONE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanStart();
    if (zoneOpen && closeDue())
    {
        closeZone();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Loading dock horn: a short blast per settled press, plus a status line.
// Horn relay on D12, dock button on D4 (pull-up).

const int HORN_PIN = 12;
const int BUTTON_PIN = 4;
const unsigned long HORN_MS = 60;
const unsigned long SETTLE_MS = 15;
const unsigned long BEAT_MS = 500;

int rawLevel = HIGH;
bool held = false;
bool hornOn = false;
unsigned long rawChangedAt = 0;
unsigned long hornStartedAt = 0;
unsigned long lastBeat = 0;
unsigned int beats = 0;

void startBlast()
{
    digitalWrite(HORN_PIN, HIGH);
    hornOn = true;
    hornStartedAt = millis();
}

void serviceHorn()
{
    if (hornOn && millis() - hornStartedAt >= HORN_MS)
    {
        digitalWrite(HORN_PIN, LOW);
        hornOn = false;
    }
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held)
        {
            startBlast();
        }
        held = down;
    }
}

void heartbeat()
{
    beats++;
    Serial.print("dock ");
    Serial.println(beats);
}

void setup()
{
    pinMode(HORN_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(HORN_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastBeat = millis();
}

void loop()
{
    scanButton();
    serviceHorn();
    if (millis() - lastBeat >= BEAT_MS)
    {
        lastBeat = millis();
        heartbeat();
    }
}
